def compute_lipschitz_robustness_radius(margin: float, lipschitz_const: float) -> float:
    if margin <= 0 or lipschitz_const <= 0:
        return 0.0
    return margin / lipschitz_const

def composition_robustness_radius(margin: float, lip_feature: float, lip_classifier: float) -> float:
    if margin <= 0 or lip_feature <= 0 or lip_classifier <= 0:
        return 0.0
    return margin / (lip_feature * lip_classifier)

def sheaf_lipschitz_globalization(margins, lipschitz_consts):
    local_radii = [m/L for m, L in zip(margins, lipschitz_consts) if m > 0 and L > 0]
    return min(local_radii) if local_radii else 0.0

def cech_cohomology_vanishes(cocycle):
    n = cocycle.shape[0]
    import numpy as np
    for i in range(n):
        for j in range(n):
            for k in range(n):
                if not np.isclose(cocycle[i,k], cocycle[i,j] + cocycle[j,k]):
                    return False, None
    potential = cocycle[0, :]
    return True, potential
